/* Formatted on 9/27/2026 10:57:59 AM (QP5 v5.362) */
DECLARE
    V_ACTIVITY_ID   RAW (16);
BEGIN
    V_ACTIVITY_ID :=
        HEXTORAW (
            REPLACE ('{{ tblApproval.selectedRow.ACTIVITY_ID }}', '-', ''));
    TALY_BO_REP.MMS_APPROVAL_PKG.DECIDE_ACTIVITY (
        P_ACTIVITY_ID        => V_ACTIVITY_ID,
        P_USER_ID            => '{{ appsmith.user.email }}',
        P_DECISION           => '{{ this.params.decision }}',
        P_REASON_CODE        => NULLIF (TRIM ('{{ this.params.reasonCode }}'), ''),
        P_DECISION_COMMENT   => NULLIF ('{{ this.params.comment }}', ''));
    COMMIT;
END;
